/* Shared map-layer system — the single source of truth for overlay layers,
 * used by BOTH the map finder and the site planner so a layer added here shows
 * up on both surfaces with no duplication.
 *
 * - STATEWIDE: overlays that apply anywhere (FEMA, NWI, TxRRC).
 * - JURISDICTION_LAYERS (from counties.js): local utility/district layers listed
 *   per county when that county is in view.
 * - ALL_LAYERS: the flattened id→config map the sync helper manages.
 * - syncOverlayLayers(): add/remove/opacity esri dynamicMapLayers on a Leaflet
 *   map to match an `overlays` state object. Both pages call this same function.
 *
 * Every endpoint is a free, keyless public ArcGIS REST service rendered
 * server-side (export image) so each agency's standard symbology comes through.
 */
import * as EL from "esri-leaflet";
import { JURISDICTION_LAYERS } from "./counties.js";
import { JURISDICTION_SOURCES, ETJ_SOURCES, roadAuthorityStyle, ROAD_AUTHORITY_LEGEND } from "./jurisdiction.js";
import { GIS_SOURCES } from "../../../shared/gis/sources.js";
import { overpassLayer, mapillaryLayer, bedrockLayer } from "./evidenceLayers.js";
import { TERRAIN_MIN_ZOOM } from "./terrainGate.js";
/* NEW-1 — every zoom gate in the app, declared in ONE leaf so the registry rows below can
 * state theirs and the Layers panel can report it as live state. `PIPELINE_VECTOR_MIN_ZOOM`
 * mirrors VECTOR_SOURCES.txrrc_pipe.query.minVectorZoom (pinned by test/layerZoomGate). */
import { OSM_MIN_ZOOM, MAPILLARY_MIN_ZOOM, SOIL_BEDROCK_MIN_ZOOM } from "./layerZoomGate.js";
const PIPELINE_VECTOR_MIN_ZOOM = 13;
import { loadTerrain } from "./terrainLazy.js";
// NEW-1 (Imagery & Layers) — the owner's contour interval (1/2/5/10 ft), a device pref; a tiny leaf, safe on the boot path.
import { getContourInterval, subscribeContourInterval } from "./contourIntervalPref.js";
import {
  isTransientStatus, dynamicLayerOptions, imageLayerOptions, featureLayerOptions, featureBaseStyle, featureRetryDecision,
  wireRasterStatus, RASTER_STALL_MS, pointSymbolOptions, identifyCapable,
} from "./layerRequest.js";
import { cachedVectorLayer, cachedPipelineLayer, cachedCorridorLayer, isPointFeature } from "./vectorOverlay.js";
// One-line predicate, needed synchronously when a layer is built — see featureHoverAttach.js for
// why the rest of the hover engine is deferred.
const hoverIdentifyEnabled = (cfg) => !!(cfg && cfg.hoverIdentify);
import { installDefaultMarkerIcon, pointToLayerFor } from "./mapSymbols.js";
import { PIPELINE_LEGEND, commodityBucketRecord } from "./pipelineCommodity.js";
import { DEFAULT_CORRIDOR_WIDTH_FT } from "./pipelineCorridor.js";
import { proxyServiceUrl } from "../../../shared/gis/gisProxyCore.js";
// NEW-2 — the baked-flood-tile DECISION only (pure, a few hundred bytes). The renderer and the
// vector-tile stack behind it are reached by dynamic import at switch-on; see floodTileLayer.js.
import { floodTilesEnabled, resolveFloodSource } from "../../../shared/gis/floodTiles.js";
import { releaseLayer } from "./tileLifecycle.js";
// NEW-1 — THE map stacking model. Every layer's pane comes from its declared ROLE
// (area under the site elements, line/point over them); nothing here picks a z-order.
import {
  rolesOf, panesForRole, panesForLayer, bandKey, configCanLift,
  PANE_AREA, PANE_LINE, PANE_AREA_LABEL, PANE_LINE_LABEL, PANE_AREA_FRONT, PANE_AREA_FRONT_LABEL,
} from "./mapStack.js";

// NEW-1 — resolve Leaflet's default marker images for the bundler before any layer is built,
// so an accidental default marker degrades to a real pin instead of a broken-image glyph.
installDefaultMarkerIcon();

export { JURISDICTION_LAYERS };

/* Layers-panel GROUP taxonomy (B898 redesign) — decision-impact order, not data-provider
 * order. Every layer config below carries a `group` (one of the keys here) + an `order`
 * (its position within that group); LayerPanel.jsx is purely data-driven off these two
 * fields instead of hard-coding which JS object renders where. Provider names (OSM/HIFLD/
 * TxRRC/COH/HCFCD/…) are never the group name and never the row label — they live in each
 * config's `source` field, surfaced only in the per-row ⓘ ("Source: …"), reusing the same
 * provenance pattern the Yield panel's SourceTag system shipped (B895). */
export const LAYER_GROUP_ORDER = ["base", "flood", "utilities", "environmental", "access", "jurisdiction"];
export const LAYER_GROUP_LABEL = {
  base: "Base & terrain",
  flood: "Flood & drainage",
  utilities: "Utilities serving the site",
  environmental: "Environmental & hazards",
  access: "Access & infrastructure",
  jurisdiction: "Jurisdictions & authority",
};

/* Consolidated-layer registry — ONE panel row drives SEVERAL underlying source adapters
 * (`cfg.mergeGroup` tags the members). This is the Water & sewer / Electric / Fire-hydrants
 * consolidation: today's provider-named rows (Houston water lines, Houston wastewater, MUD /
 * water districts, Water/sewer CCN, …) become members of one id here, each keeping its own
 * fetch untouched (see layerPanelInfo.js buildGroupSlots + LayerPanel.jsx mergeGroupRow).
 *
 * ⛔ INCLUSIVE BY DESIGN — never AHJ-exclusive (owner rule, chat NEW-2). Near a jurisdiction
 * boundary or inside an ETJ, a site can realistically be served by a NEIGHBORING provider (CCN
 * extension, wholesale supply, annexation, a nearby main) — so a merge group must never filter
 * down to "the one jurisdiction the parcel sits in." Every member always toggles together and
 * renders whatever its own source returns for the current map view (each adapter already scopes
 * itself geographically — a City-of-Houston export simply paints nothing far from Houston); nothing
 * here re-filters by the parcel's AHJ. The existing coverage/Relevance system (coverage.js) is the
 * ONLY dimming/hiding mechanism, is buffered (default ~2.5 mi, user-adjustable), and defaults to
 * "Dim" (never hides) — so a provider just across a boundary stays visible, never suppressed. The
 * per-row ⓘ lists every contributing provider by name so a user can tell whose main/territory each
 * feature belongs to. Applies to ALL THREE merge groups below, not just Water & sewer. */
export const MERGE_GROUPS = {
  /* NEW-1 (Imagery & Layers redesign) — ONE row for the boundary sets: the county line, the city
   * limits and (Texas only) the ETJ. Drives the existing keys; each member keeps its own fetch. The
   * panel reads only the members that can serve the site, so a Georgia site drives ga_county +
   * ga_city and never sees an ETJ. */
  counties_cities: {
    label: "Counties & Cities",
    note: "County lines (heavier), city limits (thin) and, in Texas, the city ETJ (dashed) — one switch for all of them.",
  },
  /* NEW-1 — ONE Pipelines row: the authoritative TxRRC lines in Texas, the four approximate EIA
   * transmission rows in Florida / Georgia (one product = one colour in every state). */
  pipelines: {
    label: "Pipelines",
    note: "Mapped pipeline routes by product. Schematic and approximate — never a survey; confirm with the title commitment, an ALTA survey and an 811 locate.",
  },
  water_sewer: {
    label: "Water & Sewer",
    note: "Mains AND service territory (who is entitled to serve — CCN/MUD) from every provider whose data reaches this area — not just the parcel's own jurisdiction, so a neighboring provider's main or territory still shows.",
  },
  electric: {
    label: "Electric",
    note: "Overhead lines, substations and poles from every source that reaches this area.",
  },
  fire_hydrants: {
    label: "Fire Hydrants",
    note: "Best-available hydrant locations from every source that reaches this area. Overlapping points from different sources are shown as each source reports them — not yet merged into one marker (follow-up: NEW-2, needs coh_hydrants converted from a raster export to a queryable vector layer before points can be compared).",
  },
};

/* Should raster (export-image) layers go through the same-origin Drive-backed cache proxy
 * (B445)? Default ON; an explicit VITE_GIS_PROXY=0/false/off is the kill switch. Safe to leave
 * on everywhere: the proxy fails open (302 → agency) and the client also one-shot falls back to
 * the direct agency URL if the proxy isn't serving (e.g. not deployed), so a layer always renders
 * — caching is a pure enhancement on top. */
export function gisProxyEnabled() {
  try {
    const v = import.meta.env && import.meta.env.VITE_GIS_PROXY;
    return v !== "0" && v !== "false" && v !== "off";
  } catch (_) { return true; }
}

/* Best-effort "as of Xm ago" age for a proxied raster layer: read the image's current proxy
 * export URL, ask the proxy's ?meta=1 sidecar how old the cached copy is, and surface it through
 * the same onStatus {ts, stale} channel the panel already renders. Never throws; if the proxy
 * isn't serving or internals are unavailable, the layer just shows no age (no regression). */
function reportCacheAge(lyr, k, onStatus) {
  try {
    const u = lyr && lyr._currentImage && lyr._currentImage._url;
    if (!u || u.indexOf("/api/gis-cache/") === -1) return;
    const metaUrl = u + (u.indexOf("?") === -1 ? "?" : "&") + "meta=1";
    fetch(metaUrl)
      .then((r) => (r && r.ok ? r.json() : null))
      .then((m) => { if (m && m.cached && typeof m.ts === "number" && lyr && lyr._map) onStatus && onStatus(k, "loaded", null, { ts: m.ts, stale: !!m.stale }); }) // B557: lyr._map guard — don't report age on a since-removed layer
      .catch(() => {});
  } catch (_) { /* age is optional */ }
}

/* NEW-1 (FL/GA pipelines) — the four EIA transmission-pipeline rows share one shape, built here so
 * the "approximate" wording, the state scope and the 811 pointer cannot drift apart across them.
 * ⛔ `states: ["FL","GA"]` is load-bearing: a Texas site must never be offered the approximate EIA
 * layer as a stand-in for the authoritative TxRRC one (the panel demotes it as "not available in
 * Texas", exactly like every other out-of-state row). The URL comes from the registry — never inline. */
const EIA_APPROX_INFO = "Approximate — major transmission lines only. No local gas mains or gathering lines, and geometry can be miles off.";
const EIA_APPROX_CAVEAT = "Not a survey and not complete. Confirm with the title commitment (easements), an ALTA survey and an 811 locate — Sunshine 811 in Florida, Georgia 811 in Georgia.";
/* NEW-2 — each EIA line is drawn in the SAME commodity class the Texas RRC layer uses for that product
 * (pipelineCommodity.js: colour, dash and weight — natural gas amber, refined/petroleum green dashed, crude
 * violet, gas liquids red), so one product reads as one colour in every state, and none is a hydrography or
 * flood blue. Solid strokes at the hierarchy's constraint ceiling (0.85, weight 3): the commodity is told apart by colour + dash, never by fading.
 * `styleFn` (not a flat colour) so an opacity change re-derives the WHOLE style rather than a bare `{opacity}`. */
const eiaPipelineRow = (regKey, { label, bucket, order, title }) => {
  const b = commodityBucketRecord(bucket);
  const w = Math.min(b.weight, 3); // the layer hierarchy caps a constraint line at 3 (the HVL class is 4 on the Texas layer)
  return {
  kind: "esriFeature", label, mergeGroup: "pipelines", // NEW-1 (Imagery & Layers) — the four EIA rows drive the ONE Pipelines row on a Florida / Georgia site
  source: "US EIA (via Esri U.S. Federal Datasets)",
  url: GIS_SOURCES[regKey].serviceUrl, minZoom: 9, color: b.color, weight: w, opacity: 0.85,
  styleFn: (_props, opacity) => ({ color: b.color, weight: w, dashArray: b.dash || null, opacity, fill: false }),
  legendDash: !!b.dash, // NEW-1 (Imagery & Layers) — the merged Pipelines key draws the same dash the map does
  hoverIdentify: true, canvasIdentify: true, hoverTitle: title + " (approximate)", hoverSource: "US EIA",
  hoverFields: [{ names: ["Pipename", "PIPENAME"] }, { names: ["Operator", "Opername", "OPERATOR"] }],
  sublabel: EIA_APPROX_INFO,
  // NEW-1 — an empty view on an APPROXIMATE, transmission-only map is not evidence of absence, so this row never says "No features".
  emptyMsg: "None mapped in this view — not proof there are none.",
  note: "US Energy Information Administration Energy Atlas — national, transmission-only. Loads zoomed in.",
  infoCaveat: EIA_APPROX_CAVEAT,
  // NEW-1 stacking role (lib/mapStack.js): pipeline centrelines.
  role: "line",
  states: ["FL", "GA"],
  group: "environmental", order,
  };
};


export const STATEWIDE = {
  fema: {
    label: "FEMA Flood Zones", swatch: "#1e9bb0",
    url: "https://hazards.fema.gov/arcgis/rest/services/public/NFHL/MapServer",
    // NFHL sublayers 27 (Flood Hazard Boundaries) + 28 (Flood Hazard Zones), standard
    // symbology. Both are scale-gated AT THE SOURCE (minScale ~1:36,112), so they only
    // draw once zoomed in to roughly neighbourhood level (~zoom 14+); at city-wide zoom
    // the export is a blank transparent PNG — that's expected, not a failure. Verified
    // rendering in a real browser 2026-06-17: teal AE floodplain / orange floodway / red
    // boundaries paint correctly along the bayous, and the host is CORS-clean (an
    // Access-Control-Allow-Origin header is present on both metadata and /export).
    layers: [27, 28],
    note: "Flood zones appear once you zoom in to about street level — hidden at city-wide zoom.",
    opacity: 0.55,
    // NEW-1 stacking role (lib/mapStack.js): NFHL 28 = Flood Hazard ZONES (filled) → under the plan; 27 = Flood Hazard BOUNDARIES (strokes) → over it.
    roleLayers: { area: [28], line: [27] },
    group: "flood", order: 1,
    // B1076 — the flood group's four tiers. FEMA is the REGULATORY tier: an adopted map a
    // floodplain administrator enforces. Never merge it with an advisory model.
    floodTier: "regulatory", agency: "FEMA",
    /* NEW-7 — an EMPTY identify from THIS layer is not "nothing here". NFHL does not cover
     * everywhere, so no polygon under the cursor means no effective flood map at that point —
     * which is the opposite risk position from "checked, and clear". The generic "Nothing here"
     * reads as the all-clear, so this row opts into the honest gap wording instead (the copy
     * itself lives in floodZone.js `FLOOD_ABSENCE`, with the panel's, so the two can't drift). */
    identifyGap: "flood",
    /* NEW-2 — this row MAY render from a baked per-county PMTiles archive instead of FEMA's live
     * /export, when the flag is on and the plan's county has one. It is the same row either way:
     * a second panel entry would double-paint and would ask the user a question about our
     * plumbing. `floodTiles` is the opt-in; `syncOverlayLayers` makes the call per plan, and a
     * missing or unreadable archive falls straight back to the raster path below. */
    floodTiles: true,
    /* ⛔ B1490144 (owner request 2026-09-10, verbatim: "remove the feature where my
     * mouse tells me the floodplain status when the floodplain layer is on") — this row is
     * excluded from EVERY cursor-driven identify, both the raster ask (`identify: false`, read by
     * `identifyCapable` in layerRequest.js, which is what `rasterIdentifyLayers` gates on — the
     * one function both the planner canvas's hover and the map finder's hover/click share) and
     * the vector/tiles ask (`canvasIdentify: false`, read by `identifyOverlaysAt`). Scoped to
     * THIS layer only — every other raster-painted layer (wetlands, the City mains, HCFCD, BKDD,
     * the wells) is untouched. The Layers panel's own FEMA verdict (`femaVerdict` in
     * components/LayerPanel.jsx, via `floodZoneCopy.femaZoneVerdict`) is a SEPARATE, deliberate
     * ask-on-purpose surface and does not read either flag — it is unaffected. `identifyGap`
     * above is left alone too: it is generic coverage-gap machinery another layer could still opt
     * into, not flood-specific code, and `test/layerConsolidation.test.js` already pins it. */
    identify: false,
    canvasIdentify: false,
  },
  wetlands: {
    kind: "dynamic", label: "Wetlands", swatch: "#2b8a6e",
    source: "National Wetlands Inventory (USFWS)",
    // CRISP VECTOR NWI — the look of the official USFWS Wetlands Mapper (true polygon outlines +
    // Cowardin class labels like PFO1A / PSS1A / PUBH), NOT a coarse raster. History: the old vector
    // host (fwspublicservices.wim.usgs.gov/wetlandsmapservice/…/Wetlands/MapServer) went down 2026-06
    // with a hard HTTP 500 across its whole catalog (B129) and is STILL 500. The new host
    // fwsprimary.wim.usgs.gov is mid-migration: its public /server/…/Wetlands/MapServer is an empty
    // dynamic shell (export + query both 500), and its Wetlands_Raster/ImageServer renders but is a
    // 100-m-per-pixel raster — it paints wetlands as ugly ~100 m BLOCKS, not real shapes (B133 shipped
    // that by mistake; B134 fixes it). The actual crisp vector polygons live in the staging service
    // Test/Wetlands_gdb_split/MapServer: layer 0 ("Wetlands") is empty; the data is split into layer
    // 1 = Wetlands_CONUS_East and layer 2 = Wetlands_CONUS_West, so we request layers:[1,2] (covers
    // the whole lower-48; Texas is in West). It's a dynamicMapLayer (esri /export f=image), like FEMA
    // — verified 2026-06-17 in a real browser: the layers=show:1,2 export returns HTTP 200 image/png
    // with true-shape polygons + labels over Sheldon Lake, and the host is CORS-clean (echoes
    // Access-Control-Allow-Origin: https://planyr.io). Source-scale-gated (layer minScale ~1:250k) —
    // like FEMA, zoom in to about city level to see polygons. CAVEAT: "Test/" is a USFWS STAGING path
    // during their host migration; it may be renamed/removed when the production Wetlands/MapServer is
    // repopulated (revisit then, or if fwspublicservices recovers). If it dies, the honest "service
    // unavailable" path (B129) still applies; the durable fix is a /server proxy through our own origin.
    url: "https://fwsprimary.wim.usgs.gov/server/rest/services/Test/Wetlands_gdb_split/MapServer",
    layers: [1, 2],
    note: "NWI is for screening only — not a jurisdictional determination.",
    opacity: 0.55,
    // NEW-1 stacking role (lib/mapStack.js): NWI Cowardin polygons render as filled shapes.
    role: "area",
    group: "environmental", order: 1,
  },
  txrrc_pipe: {
    // B751: now a VECTOR LINE layer — crisp polylines colored by commodity at working zoom,
    // falling back to the agency raster (imageFallback below) only when zoomed far out. The
    // VECTOR_SOURCES.txrrc_pipe row (vectorLayers.js) owns the /query pull + commodity styling;
    // this config is the panel/legend/fallback glue. Registry drives it — one source of truth.
    kind: "vectorLine", label: "Pipelines", mergeGroup: "pipelines",
    source: "Texas Railroad Commission (RRC)",
    legend: PIPELINE_LEGEND, // six commodity classes, named under the row while on
    // B517: the AUTHORITATIVE statewide RRC service — matches the GIS source registry
    // (sources.js `pipelines`) and the Site Analysis count path. The old Harris-County
    // republication (www.gis.hctx.net/.../TXRRC/Pipelines) is ~99.8% incomplete outside Harris.
    // Repointed (NOT deleted, per B751): this /export raster is now the FAR-OUT imageFallback.
    imageFallback: {
      url: "https://gis.rrc.texas.gov/server/rest/services/rrc_public/RRC_Public_Viewer_Srvs/MapServer",
      layers: [13], // Pipelines (polyline) — the registry's brief-verified sublayer
    },
    note: "RRC T-4 permit routes — schematic, not surveyed locations.",
    opacity: 0.85,
    // NEW-1 stacking role (lib/mapStack.js): Commodity-colored pipeline centrelines.
    role: "line",
    states: ["TX"],
    group: "environmental", order: 2,
  },
  txrrc_pipe_easement: {
    // B752: ASSUMED easement screening corridor — a translucent band off the B751 pipeline
    // centerlines (shares that pull/cache; draws only the bands, tinted by commodity, beneath the
    // lines). NOT a surveyed easement — the caveat below is as prominent as the band.
    kind: "pipelineCorridor", label: "Pipeline Easement Corridor (Assumed)", settingOf: "txrrc_pipe",
    pipelineSource: "txrrc_pipe", corridorWidth: true, // corridorWidth → LayerPanel shows the inline width control
    // NEW-1 — DECLARED so the Layers panel can say "not showing at this zoom" and offer the
    // fix. The corridor only exists where the centrelines came back as VECTORS, so its gate is
    // the pipeline source's own `query.minVectorZoom`; `test/layerZoomGate.test.js` pins the two
    // together, because a declared number that drifts from the runtime one is worse than none.
    minZoom: PIPELINE_VECTOR_MIN_ZOOM,
    opacity: 0.85,
    note: "ASSUMED screening corridor drawn off a SCHEMATIC centerline — NOT a surveyed easement. Doubly approximate (schematic line × assumed width). Confirm via title commitment / recorded easement instrument + an 811 one-call before relying on it.",
    // NEW-1 stacking role (lib/mapStack.js): A buffered band — a fill, so it goes under the plan (its centreline rides over).
    role: "area",
    states: ["TX"],
    group: "environmental", order: 3,
  },
  txrrc_wells: {
    label: "Oil & Gas Wells", swatch: "#7f1d1d",
    source: "Texas Railroad Commission (RRC)",
    // B517: authoritative statewide RRC service (see txrrc_pipe). Was the Harris-clipped host.
    url: "https://gis.rrc.texas.gov/server/rest/services/rrc_public/RRC_Public_Viewer_Srvs/MapServer",
    layers: [1], // Well Locations (point); RRC symbology shows status
    note: "Well symbols show status — active, plugged, dry hole, injection, etc.",
    opacity: 0.55,
    // NEW-1 stacking role (lib/mapStack.js): Well symbols.
    role: "point",
    states: ["TX"],
    group: "environmental", order: 4,
  },
  eia_gas: eiaPipelineRow("eiaGas", { label: "Gas Pipelines (Approx.)", title: "Natural gas pipeline", bucket: "gas", order: 8 }),
  eia_petroleum: eiaPipelineRow("eiaPetroleum", { label: "Petroleum Product Pipelines (Approx.)", title: "Petroleum product pipeline", bucket: "refined", order: 9 }),
  eia_crude: eiaPipelineRow("eiaCrude", { label: "Crude Oil Pipelines (Approx.)", title: "Crude oil pipeline", bucket: "crude", order: 10 }),
  eia_hgl: eiaPipelineRow("eiaHgl", { label: "Gas Liquids Pipelines (Approx.)", title: "Hydrocarbon gas liquids pipeline", bucket: "hvl", order: 11 }),
  ccn_service: {
    // Public-data screening PHASE 1 — water & sewer CCN service areas ("who holds the
    // certificate to serve this site"). The Site Analysis Water/Sewer CCN cards drive this
    // overlay (mapLayer: "ccn_service"). Rendered as an agency /export image (like jur_mud) so
    // the PUCT symbology comes through and it paints via a CORS-exempt <img>. The Harris County
    // GIS MapServer hosts BOTH water (layer 1) + sewer (layer 2) in EPSG:2278; its URL comes
    // from the registry (ccnSewer row) so no endpoint is inlined here. Coverage is the Houston
    // region (see the ccnSewer registry notes); the analysis WATER card reads the statewide TWDB
    // source, so a site's certificated-provider ANSWER can be more complete than this visual.
    // B898: this is now a MEMBER of the "Water & sewer" consolidated layer (mergeGroup
    // water_sewer, alongside coh_water/coh_ww/jur_mud below) — its own row/label no longer
    // shows solo; `label` here is the per-provider line the merged row's ⓘ lists.
    kind: "dynamic", label: "Water/Sewer Service Territory (CCN)", swatch: "#0e7490",
    source: "PUC CCN, via Harris County GIS",
    url: GIS_SOURCES.ccnSewer.serviceUrl, layers: [1, 2], opacity: 0.5,
    note: "PUC water (blue) + sewer (green) certificate-of-convenience service areas — who is certificated to serve retail water/sewer. A boundary is a retail monopoly to serve, NOT proof a line is in the ground. Houston-region coverage. Screening only — confirm with the utility/PUC.",
    infoCaveat: "A CCN boundary means a utility is CERTIFICATED to serve retail water/sewer here — not that a main is already built to a given parcel. Confirm service, capacity, and tap availability with the utility.",
    // NEW-1 stacking role (lib/mapStack.js): Certificated service TERRITORY polygons.
    role: "area",
    states: ["TX"],
    group: "utilities", mergeGroup: "water_sewer", order: 1,
  },
  env_lpst: {
    // Public-data screening PHASE 2 — TCEQ leaking petroleum storage tank (LPST) sites. The
    // Site Analysis "Leaking petroleum tanks" card drives this overlay (mapLayer: "env_lpst").
    // Agency /export image (MapServer, CORS-exempt <img>), URL from the registry (no inline).
    kind: "dynamic", label: "Leaking Petroleum Tanks", swatch: "#a21caf",
    source: "Texas Commission on Environmental Quality (TCEQ)",
    url: GIS_SOURCES.lpst.serviceUrl, layers: [0], opacity: 0.55,
    note: "TCEQ Leaking Petroleum Storage Tank sites — documented petroleum-UST releases. A Phase I ESA PRE-SCREEN, not a substitute. Loads zoomed in.",
    // NEW-1 stacking role (lib/mapStack.js): LPST site symbols.
    role: "point",
    states: ["TX"],
    group: "environmental", order: 6,
  },
  env_cleanups: {
    // Public-data screening PHASE 2 — EPA Superfund (NPL) + RCRA cleanup sites (FRS-derived).
    // FeatureServer point layer → esriFeature (vector markers); gated to zoomed-in (national
    // dataset). URL from the registry. Drives the "EPA Superfund / RCRA cleanups" card.
    kind: "esriFeature", label: "EPA Superfund & RCRA",
    source: "US EPA",
    url: GIS_SOURCES.epaCleanups.serviceUrl, minZoom: 11, color: "#b45309", weight: 2, opacity: 0.55,
    hoverIdentify: true, canvasIdentify: true, hoverTitle: "Cleanup site", hoverSource: "US EPA",
    hoverFields: [{ names: ["PRIMARY_NAME", "NAME", "SITE_NAME"] }, { names: ["SITE_TYPE", "PROGRAM", "TYPE"] }],
    note: "EPA 'Cleanups in My Community' — Superfund (NPL) + RCRA corrective-action sites. A Phase I ESA PRE-SCREEN, not a substitute. Loads zoomed in (national dataset).",
    // NEW-1 stacking role (lib/mapStack.js): Superfund/RCRA site points.
    role: "point",
    group: "environmental", order: 7,
  },
  faults: {
    // Public-data screening PHASE 3 — Houston-area active surface growth-fault traces. The Site
